sp_widget.client_script:
api.controller = function($scope) {

    var c = this;


    /* ============================================================
       INITIAL STATE
       ============================================================ */

    c.searchText = '';
    c.companyFilter = '';
    c.roleFilter = '';

    c.selectedOffer = null;
    c.showDocument = false;

    c.isLoading = false;


    /* ============================================================
       INITIALIZE
       ============================================================ */

    c.$onInit = function() {

        if (!c.data)
            return;

        if (!c.data.offers)
            c.data.offers = [];

        if (!c.data.stats) {

            c.data.stats = {
                total: 0,
                thisMonth: 0,
                companies: 0
            };

        }

    };


    /* ============================================================
       ROLE

       TPO + INTERVIEWER use the admin/table view.
       ============================================================ */

    c.isTPO = function() {

        return !!(
            c.data &&
            (
                c.data.isTPO ||
                c.data.isInterviewer
            )
        );

    };


    /* ============================================================
       COMPANY USER

       ONLY INTERVIEWER.

       HR IS NOT INCLUDED.
       ============================================================ */

    c.isCompanyUser = function() {

        return !!(
            c.data &&
            c.data.isInterviewer
        );

    };


    /* ============================================================
       STUDENT
       ============================================================ */

    c.hasOffer = function() {

        return !!(
            c.data &&
            c.data.offer
        );

    };


    c.isOffered = function() {

        if (!c.hasOffer())
            return false;

        var status =
            String(
                c.data.offer.status || ''
            )
            .toLowerCase()
            .trim();


        return (
            status === 'offered' ||
            status === 'accepted' ||
            status === 'offer accepted'
        );

    };


    c.isAccepted = function() {

        if (!c.hasOffer())
            return false;

        var status =
            String(
                c.data.offer.status || ''
            )
            .toLowerCase()
            .trim();


        return (
            status === 'accepted' ||
            status === 'offer accepted'
        );

    };


    /* ============================================================
       STATUS
       ============================================================ */

    c.getStatusClass = function(status) {

        status =
            String(
                status || 'offered'
            )
            .toLowerCase()
            .trim();


        if (
            status === 'accepted' ||
            status === 'offer accepted'
        ) {

            return 'nx-status-accepted';

        }


        if (
            status === 'rejected' ||
            status === 'declined'
        ) {

            return 'nx-status-rejected';

        }


        return 'nx-status-offered';

    };


    c.getStatusLabel = function(status) {

        return status || 'Offered';

    };


    /* ============================================================
       INITIAL
       ============================================================ */

    c.getInitial = function(name) {

        if (!name)
            return 'O';

        return String(name)
            .trim()
            .charAt(0)
            .toUpperCase();

    };


    /* ============================================================
       DISPLAY VALUE
       ============================================================ */

    c.displayValue = function(
        value,
        fallback
    ) {

        if (
            value === null ||
            typeof value === 'undefined' ||
            String(value).trim() === ''
        ) {

            return fallback ||
                'Not specified';

        }

        return value;

    };


    /* ============================================================
       COMPANIES
       ============================================================ */

    c.getCompanies = function() {

        var result = {};
        var companies = [];

        if (
            !c.data ||
            !c.data.offers
        )
            return companies;


        c.data.offers.forEach(
            function(offer) {

                if (
                    offer.company &&
                    !result[
                        offer.company
                    ]
                ) {

                    result[
                        offer.company
                    ] = true;

                    companies.push(
                        offer.company
                    );

                }

            }
        );


        return companies.sort();

    };


    /* ============================================================
       ROLES
       ============================================================ */

    c.getRoles = function() {

        var result = {};
        var roles = [];

        if (
            !c.data ||
            !c.data.offers
        )
            return roles;


        c.data.offers.forEach(
            function(offer) {

                if (
                    offer.jobRole &&
                    !result[
                        offer.jobRole
                    ]
                ) {

                    result[
                        offer.jobRole
                    ] = true;

                    roles.push(
                        offer.jobRole
                    );

                }

            }
        );


        return roles.sort();

    };


    /* ============================================================
       SEARCH
       ============================================================ */

    c.matchesSearch = function(offer) {

        var search =
            String(
                c.searchText || ''
            )
            .toLowerCase()
            .trim();


        if (!search)
            return true;


        var values = [

            offer.number,
            offer.student,
            offer.company,
            offer.jobRole,
            offer.package,
            offer.offerDate

        ];


        for (
            var i = 0;
            i < values.length;
            i++
        ) {

            if (
                String(
                    values[i] || ''
                )
                .toLowerCase()
                .indexOf(search) >= 0
            ) {

                return true;

            }

        }


        return false;

    };


    /* ============================================================
       FILTERS
       ============================================================ */

    c.matchesFilters = function(offer) {

        if (
            c.companyFilter &&
            offer.company !==
            c.companyFilter
        ) {

            return false;

        }


        if (
            c.roleFilter &&
            offer.jobRole !==
            c.roleFilter
        ) {

            return false;

        }


        return true;

    };


    /* ============================================================
       FILTERED OFFERS
       ============================================================ */

    c.getFilteredOffers = function() {

        if (
            !c.data ||
            !c.data.offers
        )
            return [];


        return c.data.offers.filter(
            function(offer) {

                return (
                    c.matchesSearch(
                        offer
                    ) &&
                    c.matchesFilters(
                        offer
                    )
                );

            }
        );

    };


    /* ============================================================
       CLEAR
       ============================================================ */

    c.clearFilters = function() {

        c.searchText = '';
        c.companyFilter = '';
        c.roleFilter = '';

    };


    /* ============================================================
       VIEW OFFER
       ============================================================ */

    c.viewOffer = function(offer) {

        if (!offer)
            return;

        c.selectedOffer = offer;

        c.showDocument = true;

    };


    /* ============================================================
       CLOSE OFFER
       ============================================================ */

    c.closeDocument = function() {

        c.showDocument = false;

        c.selectedOffer = null;

    };


    /* ============================================================
       DESTROY
       ============================================================ */

    $scope.$on(
        '$destroy',
        function() {

            c.selectedOffer = null;
            c.showDocument = false;

        }
    );

};

sp_widget.css:
/* ============================================================
   NEXORA OFFER MANAGEMENT
   PREMIUM SERVICE PORTAL UI
   ============================================================ */


/* ============================================================
   ROOT
   ============================================================ */

.nx-offer-page,
.nx-student-offer-page {

    --nx-navy: #17334b;
    --nx-navy-dark: #102a40;
    --nx-navy-soft: #20435d;

    --nx-coral: #ff6b5b;
    --nx-coral-dark: #ee594b;

    --nx-bg: #f5f7fa;
    --nx-card: #ffffff;

    --nx-text: #172b3f;
    --nx-muted: #718096;
    --nx-light-text: #94a3b8;

    --nx-border: #e4e9ef;
    --nx-border-light: #edf1f5;

    --nx-green: #159570;
    --nx-green-bg: #e9f8f2;

    --nx-purple: #7957c7;
    --nx-purple-bg: #f1edfb;

    --nx-blue-bg: #edf5ff;

    font-family: "Inter", -apple-system, BlinkMacSystemFont,
                 "Segoe UI", sans-serif;

    color: var(--nx-text);
}


/* ============================================================
   MAIN PAGE
   ============================================================ */

.nx-offer-page {

    width: 85vw;
    max-width: 1450px;

    margin: 0 auto;

    padding: 70px;

    box-sizing: border-box;

    background: #ffffff;
}


/* ============================================================
   HERO
   ============================================================ */

.nx-offer-hero {

    min-height: 170px;

    display: flex;
    align-items: center;
    justify-content: space-between;

    gap: 30px;

    padding: 34px 38px;

    margin-bottom: 22px;

    border-radius: 0 0 28px 28px;

    background:
        radial-gradient(
            circle at 90% 10%,
            rgba(255, 107, 91, .18),
            transparent 30%
        ),
        linear-gradient(
            135deg,
            #17334b 0%,
            #1c405b 65%,
            #204b68 100%
        );

    box-shadow:
        0 14px 35px rgba(23, 51, 75, .13);

    color: #fff;

    position: relative;

    overflow: hidden;
}


.nx-offer-hero::after {

    content: "";

    position: absolute;

    width: 260px;
    height: 260px;

    right: -90px;
    bottom: -150px;

    border-radius: 50%;

    border: 1px solid rgba(255,255,255,.10);
}


.nx-offer-hero-left {

    position: relative;
    z-index: 2;

    max-width: 760px;
}


.nx-offer-breadcrumb {

    display: flex;
    align-items: center;
    gap: 8px;

    font-size: 10px;

    font-weight: 800;

    letter-spacing: 1.5px;

    color: rgba(255,255,255,.64);

    margin-bottom: 9px;
}


.nx-breadcrumb-dot {

    width: 6px;
    height: 6px;

    border-radius: 50%;

    background: var(--nx-coral);

    box-shadow:
        0 0 0 4px rgba(255,107,91,.12);
}


.nx-offer-hero h1 {

    margin: 0;

    font-size: 34px;

    line-height: 1.15;

    font-weight: 800;

    letter-spacing: -.8px;

    color: #fff;
}


.nx-offer-hero p {

    margin: 9px 0 0;

    max-width: 650px;

    font-size: 13px;

    line-height: 1.7;

    color: rgba(255,255,255,.72);
}


.nx-offer-hero-right {

    position: relative;
    z-index: 2;

    min-width: 190px;

    text-align: right;
}


.nx-live-pill {

    display: inline-flex;

    align-items: center;
    gap: 8px;

    padding: 9px 13px;

    border-radius: 30px;

    background: rgba(255,255,255,.09);

    border: 1px solid rgba(255,255,255,.14);

    color: rgba(255,255,255,.88);

    font-size: 9px;

    font-weight: 800;

    letter-spacing: 1.1px;
}


.nx-live-dot {

    width: 7px;
    height: 7px;

    border-radius: 50%;

    background: #54d7a5;

    box-shadow:
        0 0 0 4px rgba(84,215,165,.12);
}


.nx-hero-caption {

    margin-top: 14px;

    font-size: 10px;

    font-weight: 700;

    letter-spacing: 1.8px;

    color: rgba(255,255,255,.40);
}


/* ============================================================
   STATISTICS
   ============================================================ */

.nx-offer-stats {

    display: grid;

    grid-template-columns: repeat(3, minmax(0, 1fr));

    gap: 18px;

    margin-bottom: 22px;
}


.nx-offer-stat-card {

    min-height: 145px;

    padding: 22px 24px;

    box-sizing: border-box;

    background: #fff;

    border: 1px solid var(--nx-border);

    border-radius: 17px;

    box-shadow:
        0 4px 14px rgba(23,51,75,.035);

    transition:
        transform .2s ease,
        box-shadow .2s ease,
        border-color .2s ease;
}


.nx-offer-stat-card:hover {

    transform: translateY(-2px);

    border-color: #d8e0e8;

    box-shadow:
        0 12px 25px rgba(23,51,75,.07);
}


.nx-stat-top {

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 10px;
}


.nx-stat-icon {

    width: 43px;
    height: 43px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 13px;

    flex-shrink: 0;
}


.nx-stat-icon-blue {

    background: var(--nx-blue-bg);

    color: #3678c8;
}


.nx-stat-icon-coral {

    background: #fff0ed;

    color: var(--nx-coral);
}


.nx-stat-icon-purple {

    background: var(--nx-purple-bg);

    color: var(--nx-purple);
}


.nx-stat-label {

    margin-left: auto;

    font-size: 9px;

    font-weight: 800;

    letter-spacing: 1.2px;

    color: #8190a1;
}


.nx-stat-value {

    margin-top: 15px;

    font-size: 29px;

    line-height: 1;

    font-weight: 800;

    letter-spacing: -.7px;

    color: var(--nx-text);
}


.nx-stat-bottom {

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 10px;

    margin-top: 11px;
}


.nx-stat-description {

    font-size: 11px;

    color: #8795a5;
}


.nx-stat-indicator {

    padding: 4px 7px;

    border-radius: 5px;

    background: #eef4fa;

    color: #5c7389;

    font-size: 8px;

    font-weight: 800;

    letter-spacing: .8px;
}


.nx-indicator-coral {

    background: #fff0ed;

    color: var(--nx-coral);
}


.nx-indicator-purple {

    background: var(--nx-purple-bg);

    color: var(--nx-purple);
}


/* ============================================================
   ICONS
   ============================================================ */

.nx-icon-document {

    width: 16px;
    height: 19px;

    display: inline-block;

    border: 2px solid currentColor;

    border-radius: 3px;

    position: relative;

    box-sizing: border-box;
}


.nx-icon-document::after {

    content: "";

    position: absolute;

    left: 3px;
    right: 3px;

    top: 6px;

    height: 2px;

    background: currentColor;

    box-shadow:
        0 4px 0 currentColor,
        0 8px 0 currentColor;

    opacity: .65;
}


.nx-icon-calendar {

    width: 17px;
    height: 16px;

    display: inline-block;

    border: 2px solid currentColor;

    border-radius: 4px;

    position: relative;

    box-sizing: border-box;
}


.nx-icon-calendar::before {

    content: "";

    position: absolute;

    left: -2px;
    right: -2px;

    top: 3px;

    height: 2px;

    background: currentColor;
}


.nx-icon-calendar::after {

    content: "";

    position: absolute;

    width: 3px;
    height: 3px;

    left: 4px;
    top: 8px;

    background: currentColor;

    box-shadow:
        5px 0 0 currentColor,
        0 4px 0 currentColor,
        5px 4px 0 currentColor;
}


.nx-icon-building {

    width: 17px;
    height: 18px;

    display: inline-block;

    border: 2px solid currentColor;

    border-radius: 2px;

    position: relative;

    box-sizing: border-box;
}


.nx-icon-building::after {

    content: "";

    position: absolute;

    width: 3px;
    height: 3px;

    left: 3px;
    top: 4px;

    background: currentColor;

    box-shadow:
        6px 0 0 currentColor,
        0 5px 0 currentColor,
        6px 5px 0 currentColor;
}


.nx-icon-search {

    width: 14px;
    height: 14px;

    display: inline-block;

    border: 2px solid currentColor;

    border-radius: 50%;

    position: relative;
}


.nx-icon-search::after {

    content: "";

    position: absolute;

    width: 6px;
    height: 2px;

    background: currentColor;

    right: -5px;
    bottom: -2px;

    transform: rotate(45deg);

    border-radius: 2px;
}


.nx-icon-eye {

    width: 17px;
    height: 11px;

    display: inline-block;

    border: 1.7px solid currentColor;

    border-radius: 70% 20%;

    transform: rotate(-45deg);

    position: relative;
}


.nx-icon-eye::after {

    content: "";

    width: 4px;
    height: 4px;

    position: absolute;

    left: 4px;
    top: 2px;

    border-radius: 50%;

    background: currentColor;
}


/* ============================================================
   OFFER WORKSPACE
   ============================================================ */

.nx-offer-workspace {

    background: #fff;

    border: 1px solid var(--nx-border);

    border-radius: 19px;

    overflow: hidden;

    box-shadow:
        0 5px 18px rgba(23,51,75,.035);
}


/* ============================================================
   WORKSPACE HEADER
   ============================================================ */

.nx-workspace-header {

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 20px;

    padding: 23px 25px;

    border-bottom: 1px solid var(--nx-border-light);
}


.nx-workspace-heading {

    display: flex;

    align-items: center;

    gap: 14px;

    min-width: 0;
}


.nx-workspace-icon {

    width: 44px;
    height: 44px;

    flex-shrink: 0;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 13px;

    background: var(--nx-navy);

    color: #fff;

    box-shadow:
        0 7px 14px rgba(23,51,75,.16);
}


.nx-workspace-eyebrow {

    margin-bottom: 3px;

    font-size: 8px;

    font-weight: 800;

    letter-spacing: 1.3px;

    color: var(--nx-coral);
}


.nx-workspace-heading h2 {

    margin: 0;

    font-size: 19px;

    line-height: 1.2;

    font-weight: 800;

    color: var(--nx-text);
}


.nx-workspace-heading p {

    margin: 4px 0 0;

    font-size: 11px;

    color: #8795a5;
}


.nx-record-pill {

    display: inline-flex;

    align-items: center;

    gap: 7px;

    padding: 8px 12px;

    border-radius: 20px;

    background: #f3f6f9;

    border: 1px solid #e9edf2;

    flex-shrink: 0;
}


.nx-record-pill span {

    font-size: 12px;

    font-weight: 800;

    color: var(--nx-navy);
}


.nx-record-pill small {

    font-size: 8px;

    font-weight: 800;

    letter-spacing: .8px;

    color: #8492a2;
}


/* ============================================================
   TOOLBAR
   ============================================================ */

.nx-offer-toolbar {

    display: flex;

    align-items: center;

    gap: 10px;

    padding: 15px 17px;

    background: #fbfcfd;

    border-bottom: 1px solid var(--nx-border-light);
}


.nx-search-box {

    height: 42px;

    flex: 1;

    min-width: 260px;

    display: flex;

    align-items: center;

    gap: 10px;

    padding: 0 12px;

    background: #fff;

    border: 1px solid #dfe6ed;

    border-radius: 10px;

    box-sizing: border-box;

    transition:
        border-color .2s ease,
        box-shadow .2s ease;
}


.nx-search-box:focus-within {

    border-color: rgba(255,107,91,.65);

    box-shadow:
        0 0 0 3px rgba(255,107,91,.08);
}


.nx-search-icon {

    color: #8c9bab;

    display: flex;

    align-items: center;
}


.nx-search-box input {

    flex: 1;

    min-width: 0;

    border: 0;

    outline: none;

    background: transparent;

    font-family: inherit;

    font-size: 11px;

    color: var(--nx-text);
}


.nx-search-box input::placeholder {

    color: #a0adbb;
}


.nx-search-shortcut {

    padding: 4px 6px;

    border-radius: 4px;

    background: #f2f5f8;

    color: #9aa7b5;

    font-size: 7px;

    font-weight: 800;

    letter-spacing: .7px;
}


.nx-filter-control {

    height: 42px;

    min-width: 145px;

    position: relative;

    background: #fff;

    border: 1px solid #dfe6ed;

    border-radius: 10px;

    box-sizing: border-box;

    overflow: hidden;
}


.nx-filter-label {

    position: absolute;

    top: 5px;
    left: 11px;

    z-index: 1;

    font-size: 7px;

    font-weight: 800;

    letter-spacing: .7px;

    color: #a0adba;

    pointer-events: none;
}


.nx-filter-control select {

    width: 100%;
    height: 100%;

    border: 0;
    outline: 0;

    appearance: auto;

    padding: 14px 10px 3px;

    background: transparent;

    font-family: inherit;

    font-size: 11px;

    color: var(--nx-text);

    cursor: pointer;
}


.nx-reset-btn {

    height: 42px;

    min-width: 76px;

    display: inline-flex;

    align-items: center;
    justify-content: center;

    gap: 6px;

    border: 1px solid #dfe6ed;

    border-radius: 10px;

    background: #fff;

    color: #67788a;

    font-family: inherit;

    font-size: 10px;

    font-weight: 700;

    cursor: pointer;

    transition:
        all .2s ease;
}


.nx-reset-btn:hover {

    border-color: var(--nx-coral);

    color: var(--nx-coral);

    background: #fff8f6;
}


.nx-reset-icon {

    font-size: 15px;

    line-height: 1;
}


/* ============================================================
   TABLE
   ============================================================ */

.nx-offer-table-container {

    width: 100%;

    overflow-x: auto;

    scrollbar-width: thin;
}


.nx-offer-table {

    width: 100%;

    min-width: 1040px;

    border-collapse: collapse;

    table-layout: auto;
}


.nx-offer-table thead {

    background: #f8fafc;
}


.nx-offer-table th {

    height: 42px;

    padding: 0 16px;

    text-align: left;

    white-space: nowrap;

    border-bottom: 1px solid #e9eef3;

    color: #8493a4;

    font-size: 8px;

    font-weight: 800;

    letter-spacing: 1px;
}


.nx-offer-table td {

    height: 74px;

    padding: 10px 16px;

    border-bottom: 1px solid #edf1f4;

    vertical-align: middle;

    color: #526477;

    font-size: 11px;
}


.nx-offer-table tbody tr {

    transition:
        background .18s ease;
}


.nx-offer-table tbody tr:hover {

    background: #fcfdfe;
}


.nx-offer-table tbody tr:last-child td {

    border-bottom: 0;
}


/* ============================================================
   OFFER NUMBER
   ============================================================ */

.nx-offer-number {

    display: inline-flex;

    align-items: center;

    gap: 7px;
}


.nx-offer-number-icon {

    width: 24px;
    height: 24px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 7px;

    background: #f1f5f9;

    color: #8292a2;

    font-size: 9px;

    font-weight: 800;
}


.nx-offer-number strong {

    color: var(--nx-navy);

    font-size: 10px;

    font-weight: 800;

    letter-spacing: .15px;
}


/* ============================================================
   STUDENT
   ============================================================ */

.nx-student-info {

    display: flex;

    align-items: center;

    gap: 10px;
}


.nx-student-avatar {

    width: 35px;
    height: 35px;

    flex-shrink: 0;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 10px;

    background:
        linear-gradient(
            135deg,
            #edf5ff,
            #dfeeff
        );

    color: #3974ae;

    font-size: 11px;

    font-weight: 800;

    border: 1px solid #dbe8f5;
}


.nx-student-text {

    display: flex;

    flex-direction: column;

    gap: 3px;

    min-width: 120px;
}


.nx-student-text strong {

    color: var(--nx-text);

    font-size: 11px;

    font-weight: 750;
}


.nx-student-text span {

    font-size: 8px;

    color: #9aa7b5;
}


/* ============================================================
   COMPANY
   ============================================================ */

.nx-company-cell {

    display: flex;

    align-items: center;

    gap: 8px;
}


.nx-company-mini {

    width: 27px;
    height: 27px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 8px;

    background: #f5f1ff;

    color: var(--nx-purple);

    font-size: 9px;

    font-weight: 800;
}


.nx-company-cell span {

    color: #506274;

    font-weight: 600;
}


/* ============================================================
   ROLE
   ============================================================ */

.nx-role-text {

    color: #536577;

    font-weight: 600;

    white-space: nowrap;
}


/* ============================================================
   PACKAGE
   ============================================================ */

.nx-package {

    display: flex;

    align-items: baseline;

    gap: 3px;
}


.nx-package strong {

    color: var(--nx-text);

    font-size: 12px;

    font-weight: 800;
}


.nx-package span {

    color: #8a98a7;

    font-size: 8px;

    font-weight: 800;

    letter-spacing: .5px;
}


/* ============================================================
   DATE
   ============================================================ */

.nx-date-cell {

    display: flex;

    align-items: center;

    gap: 7px;

    white-space: nowrap;
}


.nx-date-icon {

    width: 24px;
    height: 24px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 7px;

    background: #f4f7fa;

    color: #8393a4;
}


.nx-date-icon .nx-icon-calendar {

    transform: scale(.65);
}


/* ============================================================
   STATUS
   ============================================================ */

.nx-status-badge {

    display: inline-flex;

    align-items: center;

    gap: 6px;

    min-height: 25px;

    padding: 0 9px;

    border-radius: 20px;

    background: #edf8f4;

    border: 1px solid #d6f0e7;

    color: var(--nx-green);

    font-size: 8px;

    font-weight: 800;

    letter-spacing: .2px;

    white-space: nowrap;
}


.nx-status-dot {

    width: 5px;
    height: 5px;

    border-radius: 50%;

    background: currentColor;
}


/* Common ServiceNow status class compatibility */

.nx-status-badge.status-approved,
.nx-status-badge.approved,
.nx-status.approved {

    background: #edf8f4;

    color: #159570;

    border-color: #d6f0e7;
}


.nx-status-badge.status-pending,
.nx-status-badge.pending {

    background: #fff8e9;

    color: #bd7b15;

    border-color: #f6e5bb;
}


.nx-status-badge.status-rejected,
.nx-status-badge.rejected {

    background: #fff0ef;

    color: #cf5149;

    border-color: #f5d5d2;
}


/* ============================================================
   VIEW BUTTON
   ============================================================ */

.nx-view-offer-btn {

    height: 32px;

    display: inline-flex;

    align-items: center;
    justify-content: center;

    gap: 6px;

    padding: 0 9px;

    border-radius: 8px;

    border: 1px solid #dce6ef;

    background: #f7faff;

    color: #37698f;

    font-family: inherit;

    font-size: 9px;

    font-weight: 800;

    cursor: pointer;

    transition:
        all .2s ease;
}


.nx-view-offer-btn:hover {

    background: var(--nx-navy);

    border-color: var(--nx-navy);

    color: #fff;

    transform: translateY(-1px);

    box-shadow:
        0 5px 12px rgba(23,51,75,.14);
}


.nx-eye-icon {

    display: flex;

    align-items: center;
}


.nx-eye-icon .nx-icon-eye {

    transform: scale(.65) rotate(-45deg);
}


.nx-arrow {

    font-size: 13px;

    line-height: 1;

    opacity: .7;

    transition:
        transform .2s ease;
}


.nx-view-offer-btn:hover .nx-arrow {

    transform: translateX(2px);

    opacity: 1;
}


/* ============================================================
   EMPTY TABLE
   ============================================================ */

.nx-empty-cell {

    height: 330px !important;

    padding: 30px !important;

    text-align: center !important;
}


.nx-empty-state {

    display: flex;

    flex-direction: column;

    align-items: center;

    justify-content: center;
}


.nx-empty-icon {

    width: 64px;
    height: 64px;

    display: flex;

    align-items: center;
    justify-content: center;

    margin-bottom: 14px;

    border-radius: 18px;

    background: #f2f6fa;

    color: #8b9aaa;
}


.nx-empty-icon .nx-icon-document {

    transform: scale(1.15);
}


.nx-empty-state h3 {

    margin: 0;

    color: var(--nx-text);

    font-size: 15px;

    font-weight: 800;
}


.nx-empty-state p {

    margin: 6px 0 15px;

    color: #8997a6;

    font-size: 10px;
}


.nx-empty-clear {

    height: 33px;

    padding: 0 14px;

    border: 1px solid #dce5ec;

    border-radius: 8px;

    background: #fff;

    color: var(--nx-navy);

    font-family: inherit;

    font-size: 9px;

    font-weight: 800;

    cursor: pointer;
}


/* ============================================================
   FOOTER
   ============================================================ */

.nx-offer-footer {

    min-height: 47px;

    padding: 0 18px;

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 20px;

    border-top: 1px solid var(--nx-border-light);

    background: #fbfcfd;

    box-sizing: border-box;
}


.nx-footer-summary {

    display: flex;

    align-items: center;

    gap: 5px;

    font-size: 9px;

    color: #8a98a7;
}


.nx-footer-summary strong {

    color: #536678;

    font-weight: 800;
}


.nx-footer-dot {

    width: 5px;
    height: 5px;

    border-radius: 50%;

    background: #59cba0;

    margin-right: 2px;
}


.nx-footer-secure {

    display: flex;

    align-items: center;

    gap: 5px;

    color: #9aa7b5;

    font-size: 8px;

    font-weight: 700;
}


.nx-footer-secure span {

    color: #3bb78b;

    font-weight: 900;
}


/* ============================================================
   STUDENT PAGE
   ============================================================ */

.nx-student-offer-page {

    width: 85vw;

   
    margin: 0 auto;

    padding: 70px;

    box-sizing: border-box;

    background: #ffffff;
}


/* ============================================================
   STUDENT HERO
   ============================================================ */

.nx-student-hero {

    min-height: 145px;

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 20px;

    padding: 31px 35px;

    margin-bottom: 23px;

    border-radius: 20px;

    background:
        linear-gradient(
            135deg,
            #17334b,
            #20435d
        );

    color: #fff;

    box-sizing: border-box;
}


.nx-student-hero h1 {

    margin: 0;

    color: #fff;

    font-size: 31px;

    font-weight: 800;

    letter-spacing: -.7px;
}


.nx-student-hero p {

    margin: 7px 0 0;

    color: rgba(255,255,255,.68);

    font-size: 12px;
}


.nx-received-badge {

    display: inline-flex;

    align-items: center;

    gap: 7px;

    padding: 10px 13px;

    border-radius: 30px;

    background: rgba(255,255,255,.09);

    border: 1px solid rgba(255,255,255,.13);

    color: #b9f1da;

    font-size: 9px;

    font-weight: 800;

    letter-spacing: .9px;

    white-space: nowrap;
}


.nx-badge-check {

    width: 18px;
    height: 18px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background: #42bf91;

    color: #fff;

    font-size: 10px;
}


/* ============================================================
   STUDENT OFFER CARD
   ============================================================ */

.nx-student-offer-card {

    background: #fff;

    border: 1px solid var(--nx-border);

    border-radius: 20px;

    overflow: hidden;

    box-shadow:
        0 8px 28px rgba(23,51,75,.05);
}


/* ============================================================
   SUCCESS AREA
   ============================================================ */

.nx-student-success {

    display: flex;

    align-items: center;

    gap: 16px;

    padding: 25px 28px;

    background:
        linear-gradient(
            90deg,
            #f0faf6,
            #ffffff
        );

    border-bottom: 1px solid #e4f1ec;
}


.nx-success-icon {

    width: 48px;
    height: 48px;

    display: flex;

    align-items: center;
    justify-content: center;

    flex-shrink: 0;

    border-radius: 15px;

    background: #e3f7ee;

    color: #159570;

    font-size: 21px;

    font-weight: 900;

    border: 1px solid #d0eee2;
}


.nx-success-eyebrow {

    display: block;

    margin-bottom: 4px;

    color: #159570;

    font-size: 8px;

    font-weight: 800;

    letter-spacing: 1.3px;
}


.nx-student-success h2 {

    margin: 0;

    color: var(--nx-text);

    font-size: 20px;

    font-weight: 800;
}


.nx-student-success p {

    margin: 4px 0 0;

    color: #81909f;

    font-size: 10px;
}


/* ============================================================
   STUDENT COMPANY
   ============================================================ */

.nx-student-company-card {

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 20px;

    padding: 27px 28px;

    border-bottom: 1px solid var(--nx-border-light);
}


.nx-student-company-left {

    display: flex;

    align-items: center;

    gap: 15px;
}


.nx-large-company-avatar {

    width: 58px;
    height: 58px;

    display: flex;

    align-items: center;
    justify-content: center;

    flex-shrink: 0;

    border-radius: 17px;

    background:
        linear-gradient(
            135deg,
            #f3edff,
            #e9e0fb
        );

    border: 1px solid #e3d9f7;

    color: var(--nx-purple);

    font-size: 17px;

    font-weight: 800;
}


.nx-detail-eyebrow {

    display: block;

    margin-bottom: 3px;

    color: #94a1ae;

    font-size: 8px;

    font-weight: 800;

    letter-spacing: 1px;
}


.nx-student-company-left h2 {

    margin: 0;

    color: var(--nx-text);

    font-size: 20px;

    font-weight: 800;
}


.nx-student-company-left p {

    margin: 4px 0 0;

    color: #748597;

    font-size: 11px;

    font-weight: 600;
}


/* ============================================================
   PRIMARY BUTTON
   ============================================================ */

.nx-primary-offer-btn {

    height: 42px;

    display: inline-flex;

    align-items: center;
    justify-content: center;

    gap: 9px;

    padding: 0 15px;

    border: 0;

    border-radius: 10px;

    background: var(--nx-navy);

    color: #fff;

    font-family: inherit;

    font-size: 10px;

    font-weight: 800;

    cursor: pointer;

    box-shadow:
        0 7px 15px rgba(23,51,75,.15);

    transition:
        all .2s ease;
}


.nx-primary-offer-btn:hover {

    background: var(--nx-coral);

    transform: translateY(-1px);

    box-shadow:
        0 9px 18px rgba(255,107,91,.20);
}


.nx-primary-offer-btn > span:last-child {

    font-size: 15px;

    transition:
        transform .2s ease;
}


.nx-primary-offer-btn:hover > span:last-child {

    transform: translateX(3px);
}


/* ============================================================
   STUDENT DETAILS
   ============================================================ */

.nx-student-details-grid {

    display: grid;

    grid-template-columns: repeat(4, 1fr);
}


.nx-student-detail {

    min-height: 92px;

    display: flex;

    flex-direction: column;

    justify-content: center;

    gap: 8px;

    padding: 17px 23px;

    border-right: 1px solid var(--nx-border-light);

    box-sizing: border-box;
}


.nx-student-detail:last-child {

    border-right: 0;
}


.nx-student-detail > span:first-child {

    color: #8b99a7;

    font-size: 8px;

    font-weight: 800;

    letter-spacing: .9px;
}


.nx-student-detail > strong {

    color: var(--nx-text);

    font-size: 12px;

    font-weight: 800;
}


.nx-highlight-value {

    font-size: 20px !important;

    color: var(--nx-navy) !important;
}


.nx-highlight-value small {

    font-size: 8px;

    color: #8a98a7;

    margin-left: 2px;
}


/* ============================================================
   STUDENT EMPTY
   ============================================================ */

.nx-student-empty {

    min-height: 380px;

    display: flex;

    flex-direction: column;

    align-items: center;

    justify-content: center;

    padding: 50px 30px;

    box-sizing: border-box;

    background: #fff;

    border: 1px solid var(--nx-border);

    border-radius: 20px;

    text-align: center;

    box-shadow:
        0 8px 25px rgba(23,51,75,.035);
}


.nx-student-empty-icon {

    width: 72px;
    height: 72px;

    display: flex;

    align-items: center;
    justify-content: center;

    margin-bottom: 17px;

    border-radius: 21px;

    background: #f3f6f9;

    color: #8b99a8;
}


.nx-student-empty-icon .nx-icon-document {

    transform: scale(1.2);
}


.nx-empty-eyebrow {

    color: var(--nx-coral);

    font-size: 8px;

    font-weight: 800;

    letter-spacing: 1.2px;
}


.nx-student-empty h2 {

    margin: 8px 0 5px;

    color: var(--nx-text);

    font-size: 20px;

    font-weight: 800;
}


.nx-student-empty p {

    max-width: 450px;

    margin: 0;

    color: #8997a6;

    font-size: 11px;

    line-height: 1.7;
}


.nx-empty-info {

    margin-top: 18px;

    display: inline-flex;

    align-items: center;

    gap: 7px;

    padding: 8px 12px;

    border-radius: 8px;

    background: #f7f9fb;

    color: #8795a4;

    font-size: 9px;
}


.nx-empty-info span {

    width: 16px;
    height: 16px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background: #e8eef4;

    color: #708295;

    font-size: 9px;

    font-weight: 800;
}


/* ============================================================
   MODAL OVERLAY
   ============================================================ */

.nx-offer-modal-overlay {

    position: fixed;

    inset: 0;

    z-index: 99999;

    display: flex;

    align-items: center;

    justify-content: center;

    padding: 30px;

    box-sizing: border-box;

    background:
        rgba(10, 26, 40, .70);

    backdrop-filter: blur(6px);

    -webkit-backdrop-filter: blur(6px);
}


/* ============================================================
   MODAL
   ============================================================ */

.nx-offer-modal {

    width: min(940px, 96vw);

    max-height: 92vh;

    display: flex;

    flex-direction: column;

    background: #f1f4f7;

    border-radius: 18px;

    overflow: hidden;

    box-shadow:
        0 30px 80px rgba(5,18,30,.38);

    animation:
        nxOfferModalIn .22s ease-out;
}


@keyframes nxOfferModalIn {

    from {

        opacity: 0;

        transform: translateY(12px) scale(.985);

    }

    to {

        opacity: 1;

        transform: translateY(0) scale(1);

    }

}


/* ============================================================
   MODAL TOP BAR
   ============================================================ */

.nx-modal-topbar {

    min-height: 70px;

    padding: 0 20px 0 22px;

    display: flex;

    align-items: center;

    justify-content: space-between;

    background: #fff;

    border-bottom: 1px solid #e3e8ed;

    box-sizing: border-box;
}


.nx-modal-heading {

    display: flex;

    align-items: center;

    gap: 11px;
}


.nx-modal-document-icon {

    width: 39px;
    height: 39px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 11px;

    background: var(--nx-navy);

    color: #fff;
}


.nx-modal-document-icon .nx-icon-document {

    transform: scale(.72);
}


.nx-modal-heading > div:last-child {

    display: flex;

    flex-direction: column;

    gap: 2px;
}


.nx-modal-heading span {

    color: #9aa7b5;

    font-size: 7px;

    font-weight: 800;

    letter-spacing: 1.1px;
}


.nx-modal-heading h2 {

    margin: 0;

    color: var(--nx-text);

    font-size: 15px;

    font-weight: 800;
}


.nx-modal-close {

    width: 35px;
    height: 35px;

    display: flex;

    align-items: center;
    justify-content: center;

    border: 1px solid #e0e6eb;

    border-radius: 9px;

    background: #fff;

    color: #718092;

    font-family: Arial, sans-serif;

    font-size: 24px;

    font-weight: 300;

    line-height: 1;

    cursor: pointer;

    transition:
        all .2s ease;
}


.nx-modal-close:hover {

    color: #fff;

    background: var(--nx-coral);

    border-color: var(--nx-coral);

    transform: rotate(90deg);
}


/* ============================================================
   LETTER SCROLL
   ============================================================ */

.nx-letter-scroll {

    flex: 1;

    overflow-y: auto;

    padding: 30px;

    box-sizing: border-box;

    scrollbar-width: thin;

    scrollbar-color: #cbd5df transparent;
}


/* ============================================================
   LETTER
   ============================================================ */

.nx-letter {

    max-width: 790px;

    min-height: 980px;

    margin: 0 auto;

    background: #fff;

    box-shadow:
        0 12px 30px rgba(23,51,75,.08);

    box-sizing: border-box;

    position: relative;
}


/* ============================================================
   LETTER HEADER
   ============================================================ */

.nx-letter-header {

    min-height: 120px;

    padding: 28px 34px;

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 25px;

    box-sizing: border-box;
}


.nx-letter-company-block {

    display: flex;

    align-items: center;

    gap: 13px;
}


.nx-letter-logo {

    width: 48px;
    height: 48px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 12px;

    background: var(--nx-navy);

    color: #fff;

    font-size: 17px;

    font-weight: 800;
}


.nx-letter-company {

    color: var(--nx-navy);

    font-size: 16px;

    font-weight: 800;
}


.nx-letter-company-sub {

    margin-top: 3px;

    color: var(--nx-coral);

    font-size: 7px;

    font-weight: 800;

    letter-spacing: 1.2px;
}


.nx-letter-meta {

    display: flex;

    align-items: flex-start;

    gap: 25px;

    text-align: right;
}


.nx-letter-meta > div {

    display: flex;

    flex-direction: column;

    gap: 5px;
}


.nx-letter-meta span {

    color: #98a4b0;

    font-size: 7px;

    font-weight: 800;

    letter-spacing: .8px;
}


.nx-letter-meta strong {

    color: var(--nx-text);

    font-size: 9px;

    font-weight: 800;
}


/* ============================================================
   LETTER DIVIDER
   ============================================================ */

.nx-letter-divider {

    height: 3px;

    margin: 0 34px;

    background:
        linear-gradient(
            90deg,
            var(--nx-coral) 0 24%,
            var(--nx-navy) 24% 100%
        );

    border-radius: 5px;
}


/* ============================================================
   LETTER TITLE
   ============================================================ */

.nx-letter-title {

    padding: 45px 55px 25px;

    text-align: center;
}


.nx-letter-title > span {

    color: var(--nx-coral);

    font-size: 7px;

    font-weight: 800;

    letter-spacing: 1.7px;
}


.nx-letter-title h1 {

    margin: 9px 0 11px;

    color: var(--nx-navy);

    font-size: 25px;

    font-weight: 800;

    letter-spacing: -.3px;

    text-transform: uppercase;
}


.nx-title-line {

    width: 46px;
    height: 3px;

    margin: 0 auto;

    border-radius: 4px;

    background: var(--nx-coral);
}


/* ============================================================
   LETTER CONTENT
   ============================================================ */

.nx-letter-content {

    padding: 8px 55px 40px;

    color: #46586a;

    font-family:
        "Inter",
        -apple-system,
        BlinkMacSystemFont,
        "Segoe UI",
        sans-serif;

    font-size: 11px;

    line-height: 1.85;
}


.nx-letter-content p {

    margin: 0 0 17px;
}


.nx-letter-content strong {

    color: var(--nx-text);

    font-weight: 750;
}


/* ============================================================
   LETTER DETAILS
   ============================================================ */

.nx-letter-details {

    display: grid;

    grid-template-columns: repeat(2, 1fr);

    margin: 27px 0;

    border: 1px solid #e5e9ee;

    border-radius: 10px;

    overflow: hidden;

    background: #fafbfc;
}


.nx-letter-detail {

    min-height: 62px;

    display: flex;

    flex-direction: column;

    justify-content: center;

    gap: 5px;

    padding: 10px 14px;

    border-right: 1px solid #e5e9ee;

    border-bottom: 1px solid #e5e9ee;

    box-sizing: border-box;
}


.nx-letter-detail:nth-child(even) {

    border-right: 0;
}


.nx-letter-detail:nth-last-child(-n+2) {

    border-bottom: 0;
}


.nx-letter-detail span {

    color: #8e9aa7;

    font-size: 7px;

    font-weight: 800;

    letter-spacing: .8px;
}


.nx-letter-detail strong {

    color: var(--nx-text);

    font-size: 10px;

    font-weight: 750;

    line-height: 1.3;
}


/* ============================================================
   SIGNATURE
   ============================================================ */

.nx-letter-signature {

    margin-top: 38px;

    display: flex;

    flex-direction: column;

    align-items: flex-start;

    gap: 2px;
}


.nx-letter-signature p {

    margin: 0 0 7px;

    color: #69798a;
}


.nx-letter-signature strong {

    color: var(--nx-navy);

    font-size: 11px;
}


.nx-letter-signature span {

    color: #8b98a6;

    font-size: 9px;
}


/* ============================================================
   LETTER FOOTER
   ============================================================ */

.nx-letter-footer {

    min-height: 48px;

    margin-top: 20px;

    padding: 0 34px;

    display: flex;

    align-items: center;

    justify-content: space-between;

    border-top: 1px solid #e6eaee;

    background: #fafbfc;

    color: #9aa6b2;

    font-size: 7px;

    font-weight: 800;

    letter-spacing: .8px;

    box-sizing: border-box;
}


/* ============================================================
   SCROLLBAR
   ============================================================ */

.nx-offer-table-container::-webkit-scrollbar,
.nx-letter-scroll::-webkit-scrollbar {

    width: 6px;
    height: 6px;
}


.nx-offer-table-container::-webkit-scrollbar-track,
.nx-letter-scroll::-webkit-scrollbar-track {

    background: transparent;
}


.nx-offer-table-container::-webkit-scrollbar-thumb,
.nx-letter-scroll::-webkit-scrollbar-thumb {

    background: #cbd5df;

    border-radius: 10px;
}


.nx-offer-table-container::-webkit-scrollbar-thumb:hover,
.nx-letter-scroll::-webkit-scrollbar-thumb:hover {

    background: #aebbc7;
}


/* ============================================================
   RESPONSIVE — TABLET
   ============================================================ */

@media (max-width: 1100px) {

    .nx-offer-page {

        padding-left: 25px;
        padding-right: 25px;

    }


    .nx-offer-stats {

        grid-template-columns: repeat(2, 1fr);

    }


    .nx-offer-stat-card:last-child {

        grid-column: span 2;

    }


    .nx-student-details-grid {

        grid-template-columns: repeat(2, 1fr);

    }


    .nx-student-detail:nth-child(2) {

        border-right: 0;

    }


    .nx-student-detail:nth-child(1),
    .nx-student-detail:nth-child(2) {

        border-bottom: 1px solid var(--nx-border-light);

    }


    .nx-offer-toolbar {

        flex-wrap: wrap;

    }


    .nx-search-box {

        flex-basis: 100%;

    }

}


/* ============================================================
   RESPONSIVE — MOBILE
   ============================================================ */

@media (max-width: 760px) {

    .nx-offer-page,
    .nx-student-offer-page {

        padding: 18px 13px 35px;

    }


    .nx-offer-hero {

        min-height: auto;

        padding: 25px 22px;

        border-radius: 16px;

        flex-direction: column;

        align-items: flex-start;

    }


    .nx-offer-hero h1 {

        font-size: 27px;

    }


    .nx-offer-hero-right {

        text-align: left;

    }


    .nx-offer-stats {

        grid-template-columns: 1fr;

    }


    .nx-offer-stat-card:last-child {

        grid-column: auto;

    }


    .nx-workspace-header {

        align-items: flex-start;

        padding: 19px;

    }


    .nx-record-pill {

        margin-top: 2px;

    }


    .nx-offer-toolbar {

        padding: 13px;

        align-items: stretch;

    }


    .nx-search-box {

        min-width: 100%;

    }


    .nx-filter-control {

        flex: 1;

        min-width: 0;

    }


    .nx-reset-btn {

        min-width: 75px;

    }


    .nx-offer-footer {

        min-height: auto;

        padding: 12px 15px;

        flex-direction: column;

        align-items: flex-start;

        gap: 8px;

    }


    .nx-student-hero {

        padding: 25px 22px;

        flex-direction: column;

        align-items: flex-start;

    }


    .nx-student-company-card {

        flex-direction: column;

        align-items: flex-start;

    }


    .nx-primary-offer-btn {

        width: 100%;

    }


    .nx-student-details-grid {

        grid-template-columns: 1fr;

    }


    .nx-student-detail {

        border-right: 0;

        border-bottom: 1px solid var(--nx-border-light);

    }


    .nx-student-detail:last-child {

        border-bottom: 0;

    }


    .nx-student-company-left {

        width: 100%;

    }


    .nx-offer-modal-overlay {

        padding: 10px;

    }


    .nx-offer-modal {

        width: 100%;

        max-height: 96vh;

        border-radius: 14px;

    }


    .nx-letter-scroll {

        padding: 15px;

    }


    .nx-letter {

        min-height: auto;

    }


    .nx-letter-header {

        padding: 22px;

        flex-direction: column;

        align-items: flex-start;

    }


    .nx-letter-meta {

        width: 100%;

        justify-content: flex-start;

        text-align: left;

    }


    .nx-letter-title {

        padding: 35px 25px 20px;

    }


    .nx-letter-title h1 {

        font-size: 20px;

    }


    .nx-letter-content {

        padding: 8px 25px 30px;

    }


    .nx-letter-details {

        grid-template-columns: 1fr;

    }


    .nx-letter-detail,
    .nx-letter-detail:nth-child(even),
    .nx-letter-detail:nth-last-child(-n+2) {

        border-right: 0;

        border-bottom: 1px solid #e5e9ee;

    }


    .nx-letter-detail:last-child {

        border-bottom: 0;

    }


    .nx-letter-footer {

        padding: 0 20px;

    }

}


/* ============================================================
   VERY SMALL SCREENS
   ============================================================ */

@media (max-width: 480px) {

    .nx-offer-hero h1 {

        font-size: 24px;

    }


    .nx-workspace-heading p {

        display: none;

    }


    .nx-workspace-heading h2 {

        font-size: 16px;

    }


    .nx-filter-control {

        width: 100%;

        flex-basis: 100%;

    }


    .nx-reset-btn {

        width: 100%;

    }


    .nx-student-company-left {

        align-items: flex-start;

    }


    .nx-large-company-avatar {

        width: 48px;
        height: 48px;

        border-radius: 14px;

    }


    .nx-student-company-left h2 {

        font-size: 17px;

    }


    .nx-modal-topbar {

        padding: 0 13px 0 15px;

    }


    .nx-letter-header {

        padding: 18px;

    }


    .nx-letter-divider {

        margin: 0 18px;

    }


    .nx-letter-title {

        padding-left: 18px;
        padding-right: 18px;

    }


    .nx-letter-content {

        padding-left: 18px;
        padding-right: 18px;

    }

}

sp_widget.link:
api.controller = function($scope) {

    var c = this;


    c.searchText = '';
    c.companyFilter = '';
    c.roleFilter = '';

    c.selectedOffer = null;

    c.showDocument = false;

    c.isLoading = false;


    /*
     * INITIALIZE
     */
    c.$onInit = function() {

        if (!c.data)
            return;


        if (!c.data.offers)
            c.data.offers = [];


        if (!c.data.stats) {

            c.data.stats = {

                total: 0,

                thisMonth: 0,

                companies: 0

            };

        }

    };


    /*
     * ADMIN TABLE VIEW
     *
     * TPO
     * Interviewer
     */
    c.isTPO = function() {

        return !!(
            c.data &&
            (
                c.data.isTPO ||
                c.data.isInterviewer
            )
        );

    };


    /*
     * COMPANY USER
     *
     * ONLY INTERVIEWER
     */
    c.isCompanyUser = function() {

        return !!(
            c.data &&
            c.data.isInterviewer
        );

    };


    /*
     * STUDENT OFFER EXISTS
     */
    c.hasOffer = function() {

        return !!(
            c.data &&
            c.data.offer
        );

    };


    /*
     * OFFERED STATUS
     */
    c.isOffered = function() {

        if (!c.hasOffer())
            return false;


        var status =
            String(
                c.data.offer.status || ''
            )
            .toLowerCase()
            .trim();


        return (
            status === 'offered' ||
            status === 'accepted' ||
            status === 'offer accepted'
        );

    };


    /*
     * ACCEPTED STATUS
     */
    c.isAccepted = function() {

        if (!c.hasOffer())
            return false;


        var status =
            String(
                c.data.offer.status || ''
            )
            .toLowerCase()
            .trim();


        return (
            status === 'accepted' ||
            status === 'offer accepted'
        );

    };


    /*
     * STATUS CSS
     */
    c.getStatusClass = function(status) {

        status =
            String(
                status || 'offered'
            )
            .toLowerCase()
            .trim();


        if (
            status === 'accepted' ||
            status === 'offer accepted'
        ) {

            return 'nx-status-accepted';

        }


        if (
            status === 'rejected' ||
            status === 'declined'
        ) {

            return 'nx-status-rejected';

        }


        return 'nx-status-offered';

    };


    /*
     * STATUS LABEL
     */
    c.getStatusLabel = function(status) {

        return status || 'Offered';

    };


    /*
     * STUDENT INITIAL
     */
    c.getInitial = function(name) {

        if (!name)
            return 'O';


        return String(name)
            .trim()
            .charAt(0)
            .toUpperCase();

    };


    /*
     * DISPLAY VALUE
     */
    c.displayValue = function(
        value,
        fallback
    ) {

        if (
            value === null ||
            typeof value === 'undefined' ||
            String(value).trim() === ''
        ) {

            return fallback ||
                'Not specified';

        }


        return value;

    };


    /*
     * COMPANY LIST
     *
     * USED BY TPO ONLY
     */
    c.getCompanies = function() {

        var result = {};

        var companies = [];


        if (
            !c.data ||
            !c.data.offers
        ) {

            return companies;

        }


        c.data.offers.forEach(
            function(offer) {

                if (
                    offer.company &&
                    !result[
                        offer.company
                    ]
                ) {

                    result[
                        offer.company
                    ] = true;


                    companies.push(
                        offer.company
                    );

                }

            }
        );


        return companies.sort();

    };


    /*
     * ROLE LIST
     */
    c.getRoles = function() {

        var result = {};

        var roles = [];


        if (
            !c.data ||
            !c.data.offers
        ) {

            return roles;

        }


        c.data.offers.forEach(
            function(offer) {

                if (
                    offer.jobRole &&
                    !result[
                        offer.jobRole
                    ]
                ) {

                    result[
                        offer.jobRole
                    ] = true;


                    roles.push(
                        offer.jobRole
                    );

                }

            }
        );


        return roles.sort();

    };


    /*
     * SEARCH
     */
    c.matchesSearch = function(
        offer
    ) {

        var search =
            String(
                c.searchText || ''
            )
            .toLowerCase()
            .trim();


        if (!search)
            return true;


        var values = [

            offer.number,

            offer.student,

            offer.company,

            offer.jobRole,

            offer.package,

            offer.offerDate

        ];


        for (
            var i = 0;
            i < values.length;
            i++
        ) {

            if (
                String(
                    values[i] || ''
                )
                .toLowerCase()
                .indexOf(search) >= 0
            ) {

                return true;

            }

        }


        return false;

    };


    /*
     * FILTERS
     */
    c.matchesFilters = function(
        offer
    ) {

        /*
         * COMPANY FILTER
         *
         * ONLY TPO CAN USE IT.
         *
         * Interviewer already receives
         * only their company records
         * from the Server Script.
         */
        if (
            !c.isCompanyUser() &&
            c.companyFilter &&
            offer.company !==
                c.companyFilter
        ) {

            return false;

        }


        /*
         * ROLE FILTER
         */
        if (
            c.roleFilter &&
            offer.jobRole !==
                c.roleFilter
        ) {

            return false;

        }


        return true;

    };


    /*
     * FILTERED OFFERS
     */
    c.getFilteredOffers = function() {

        if (
            !c.data ||
            !c.data.offers
        ) {

            return [];

        }


        return c.data.offers.filter(
            function(offer) {

                return (
                    c.matchesSearch(
                        offer
                    ) &&
                    c.matchesFilters(
                        offer
                    )
                );

            }
        );

    };


    /*
     * CLEAR FILTERS
     */
    c.clearFilters = function() {

        c.searchText = '';

        c.companyFilter = '';

        c.roleFilter = '';

    };


    /*
     * VIEW OFFER
     */
    c.viewOffer = function(
        offer
    ) {

        if (!offer)
            return;


        c.selectedOffer =
            offer;


        c.showDocument =
            true;

    };


    /*
     * CLOSE OFFER
     */
    c.closeDocument = function() {

        c.showDocument =
            false;


        c.selectedOffer =
            null;

    };


    /*
     * CLEANUP
     */
    $scope.$on(
        '$destroy',
        function() {

            c.selectedOffer =
                null;


            c.showDocument =
                false;

        }
    );

};

sp_widget.script:
(function() {

    /* ============================================================
       NEXORA - OFFER LETTER WIDGET
       SERVER SCRIPT
       TPO + INTERVIEWER + STUDENT
       ============================================================ */

    var OFFER_TABLE =
        'x_snc_college_pl_0_offer_letter';

    var STUDENT_TABLE =
        'x_snc_college_pl_0_student';

    var COMPANY_TABLE =
        'x_snc_college_pl_0_company';

    var APPLICATION_TABLE =
        'x_snc_college_pl_0_application';

    var INTERVIEW_TABLE =
        'x_snc_college_pl_0_interview';
	var PC_ROLE =
        'x_snc_college_pl_0.placement_officer';

    var TPO_ROLE =
        'x_snc_college_pl_0.placement_admin';

    var INTERVIEWER_ROLE =
        'x_snc_college_pl_0.interviewer';


    /* ============================================================
       ROLE
       ============================================================ */
	data.isPC =
        gs.hasRole(PC_ROLE);
    data.isTPO =
        gs.hasRole(TPO_ROLE);

    data.isInterviewer =
        gs.hasRole(INTERVIEWER_ROLE);


    data.offers = [];
    data.offer = null;
    data.error = '';


    data.stats = {
        total: 0,
        thisMonth: 0,
        companies: 0
    };


    /* ============================================================
       CURRENT USER
       ============================================================ */

    var currentUserId =
        gs.getUserID();


    /* ============================================================
       HELPER
       ============================================================ */

    function getValue(gr, field) {

        if (!gr.isValidField(field))
            return '';

        return gr.getDisplayValue(field) || '';

    }


    /* ============================================================
       INTERVIEWER ACCESS

       For Interviewer:

       1. Company.hr_user = current interviewer
       OR
       2. Interview.interviewer = current interviewer
          and Interview.application is linked to the offer

       This keeps access limited to relevant offers.
       ============================================================ */

    var companyIds = [];
    var applicationIds = [];


    /*
     * ------------------------------------------------------------
     * 1. FIND COMPANIES DIRECTLY ASSOCIATED WITH INTERVIEWER
     * ------------------------------------------------------------
     */

    if (data.isInterviewer) {

        var companyGR =
            new GlideRecord(COMPANY_TABLE);

        if (companyGR.isValid()) {

            if (
                companyGR.isValidField('hr_user')
            ) {

                companyGR.addQuery(
                    'hr_user',
                    currentUserId
                );

                companyGR.query();

                while (companyGR.next()) {

                    companyIds.push(
                        companyGR.getUniqueValue()
                    );

                }

            }

        }


        /*
         * --------------------------------------------------------
         * 2. FIND APPLICATIONS DIRECTLY ASSIGNED TO INTERVIEWER
         * --------------------------------------------------------
         */

        var interviewGR =
            new GlideRecord(INTERVIEW_TABLE);

        if (interviewGR.isValid()) {

            if (
                interviewGR.isValidField('interviewer') &&
                interviewGR.isValidField('application')
            ) {

                interviewGR.addQuery(
                    'interviewer',
                    currentUserId
                );

                interviewGR.query();

                while (interviewGR.next()) {

                    var applicationId =
                        interviewGR.getValue(
                            'application'
                        );

                    if (
                        applicationId &&
                        applicationIds.indexOf(
                            applicationId
                        ) === -1
                    ) {

                        applicationIds.push(
                            applicationId
                        );

                    }

                }

            }

        }


        /*
         * --------------------------------------------------------
         * 3. FOR DIRECTLY ASSIGNED APPLICATIONS,
         *    FIND THEIR COMPANY
         * --------------------------------------------------------
         *
         * Application
         *     -> Drive
         *     -> Company
         *
         * This makes the access work even when Company.hr_user
         * is not populated for the interviewer.
         */

        if (
            applicationIds.length > 0
        ) {

            var assignedApplicationGR =
                new GlideRecord(
                    APPLICATION_TABLE
                );

            if (
                assignedApplicationGR.isValid()
            ) {

                assignedApplicationGR.addQuery(
                    'sys_id',
                    'IN',
                    applicationIds.join(',')
                );

                assignedApplicationGR.query();

                while (
                    assignedApplicationGR.next()
                ) {

                    /*
                     * Get Drive
                     */

                    var driveId =
                        assignedApplicationGR.getValue(
                            'drive'
                        );

                    if (!driveId)
                        continue;


                    /*
                     * Get Drive record
                     */

                    var driveGR =
                        new GlideRecord(
                            'x_snc_college_pl_0_placement_drive'
                        );

                    if (
                        driveGR.get(
                            driveId
                        )
                    ) {

                        var driveCompanyId =
                            driveGR.getValue(
                                'company'
                            );

                        if (
                            driveCompanyId &&
                            companyIds.indexOf(
                                driveCompanyId
                            ) === -1
                        ) {

                            companyIds.push(
                                driveCompanyId
                            );

                        }

                    }

                }

            }

        }

    }


    /* ============================================================
       FIND STUDENT
       ============================================================ */

    var studentSysId = '';

    var studentGR =
        new GlideRecord(STUDENT_TABLE);

    if (studentGR.isValid()) {

        if (
            studentGR.isValidField('user')
        ) {

            studentGR.addQuery(
                'user',
                currentUserId
            );

            studentGR.setLimit(1);

            studentGR.query();

            if (studentGR.next()) {

                studentSysId =
                    studentGR.getUniqueValue();

            }

        }

    }


    /* ============================================================
       OFFER TABLE
       ============================================================ */

    var offerGR =
        new GlideRecord(OFFER_TABLE);

    if (!offerGR.isValid()) {

        data.error =
            'Offer Letter table not found: ' +
            OFFER_TABLE;

        return;

    }


    /* ============================================================
       ACCESS CONTROL
       ============================================================ */


    /*
     * ============================================================
     * TPO
     *
     * TPO sees ALL offer letters.
     * ============================================================
     */

    if (data.isTPO||data.isPC) {

        // DO NOT ADD ANY FILTER.
        // TPO sees everything.

    }


    /*
     * ============================================================
     * INTERVIEWER
     *
     * Interviewer sees:
     *
     * 1. Offers belonging to their company
     *
     * OR
     *
     * 2. Offers belonging to applications directly assigned
     *    to that interviewer.
     * ============================================================
     */

    else if (data.isInterviewer) {

        /*
         * No company and no application access
         */

        if (
            companyIds.length === 0 &&
            applicationIds.length === 0
        ) {

            data.error =
                'No applications or company is associated with this interviewer.';

            return;

        }


        /*
         * Check available fields
         */

        var hasCompanyField =
            offerGR.isValidField('company');

        var hasApplicationField =
            offerGR.isValidField('application');


        if (
            !hasCompanyField &&
            !hasApplicationField
        ) {

            data.error =
                'Neither Company nor Application field was found in Offer Letter table.';

            return;

        }


        /*
         * --------------------------------------------------------
         * COMPANY ACCESS
         * --------------------------------------------------------
         */

        var interviewerOfferQuery = null;


        if (
            hasCompanyField &&
            companyIds.length > 0
        ) {

            interviewerOfferQuery =
                offerGR.addQuery(
                    'company',
                    'IN',
                    companyIds.join(',')
                );

        }


        /*
         * --------------------------------------------------------
         * APPLICATION ACCESS
         * --------------------------------------------------------
         *
         * If the interviewer is directly assigned to an
         * application, allow the corresponding offer letter too.
         */

        if (
            hasApplicationField &&
            applicationIds.length > 0
        ) {

            if (
                interviewerOfferQuery
            ) {

                interviewerOfferQuery.addOrCondition(
                    'application',
                    'IN',
                    applicationIds.join(',')
                );

            } else {

                offerGR.addQuery(
                    'application',
                    'IN',
                    applicationIds.join(',')
                );

            }

        }

    }


    /*
     * ============================================================
     * STUDENT
     *
     * Student sees only their own offer letters.
     * ============================================================
     */

    else {

        if (!studentSysId) {

            data.error =
                'Student profile not found for the logged-in user.';

            return;

        }


        if (
            !offerGR.isValidField('student')
        ) {

            data.error =
                'Student field not found in Offer Letter table.';

            return;

        }


        offerGR.addQuery(
            'student',
            studentSysId
        );

    }


    /* ============================================================
       ORDER
       ============================================================ */

    if (
        offerGR.isValidField('offer_date')
    ) {

        offerGR.orderByDesc(
            'offer_date'
        );

    } else {

        offerGR.orderByDesc(
            'sys_created_on'
        );

    }


    offerGR.query();


    /* ============================================================
       BUILD OFFER DATA
       ============================================================ */

    var companyMap = {};


    while (offerGR.next()) {

        var offer = {};


        offer.sys_id =
            offerGR.getUniqueValue();


        offer.number =
            getValue(
                offerGR,
                'offer_number'
            );


        offer.student =
            getValue(
                offerGR,
                'student'
            );


        offer.company =
            getValue(
                offerGR,
                'company'
            );


        offer.jobRole =
            getValue(
                offerGR,
                'job_role'
            );


        offer.package =
            getValue(
                offerGR,
                'package'
            );


        offer.offerDate =
            getValue(
                offerGR,
                'offer_date'
            );


        offer.joiningDate =
            getValue(
                offerGR,
                'joining_date'
            );


        /*
         * STATUS IS ONLY READ.
         * NOTHING IS CHANGED.
         */

        offer.status =
            getValue(
                offerGR,
                'status'
            );


        if (!offer.status) {

            offer.status =
                'Offered';

        }


        /* ========================================================
           APPLICATION
           ======================================================== */

        if (
            offerGR.isValidField(
                'application'
            )
        ) {

            offer.application =
                getValue(
                    offerGR,
                    'application'
                );

        } else {

            offer.application = '';

        }


        /* ========================================================
           COMPANY COUNT
           ======================================================== */

        if (
            offer.company &&
            !companyMap[
                offer.company
            ]
        ) {

            companyMap[
                offer.company
            ] = true;

        }


        data.offers.push(
            offer
        );

    }


    /* ============================================================
       STATISTICS
       ============================================================ */

    data.stats.total =
        data.offers.length;


    var now =
        new GlideDateTime();


    var currentMonth =
        now.getYearLocalTime() +
        '-' +
        now.getMonthLocalTime();


    var monthCount = 0;


    for (
        var i = 0;
        i < data.offers.length;
        i++
    ) {

        var offerDate =
            data.offers[i].offerDate;


        if (offerDate) {

            var dateString =
                String(offerDate);


            if (
                dateString.indexOf(
                    currentMonth
                ) === 0
            ) {

                monthCount++;

            }

        }

    }


    data.stats.thisMonth =
        monthCount;


    data.stats.companies =
        Object.keys(
            companyMap
        ).length;


    /* ============================================================
       STUDENT OFFER
       ============================================================ */

    if (
        !data.isTPO &&
        !data.isInterviewer
    ) {

        if (
            data.offers.length > 0
        ) {

            data.offer =
                data.offers[0];

        }

    }

})();
